"""CH10b actual Home routes, raw-data arithmetic, and module cleanup."""
from pathlib import Path
import subprocess
import sys
import unittest

class CH10bWorkflows(unittest.TestCase):
    def test_all_calculation_routes(self):
        code="import builtins,contextlib,io,sys,weakref\nimport STAT1,STCORE as c\nc.wait_key=lambda:'right';viewer=c.view\ncases=[('Q1', ['15', '4', 'Q1', '1', '2', '0', '0.1', '1', '1', '128', '49', '42', '', '1', '117', '28', '52', '', '0', '0', '0'], 1.2941750600553275, 0.10020203532826828, ['FAIL TO REJECT H0']), ('Q2', ['15', '4', 'Q2', '3', '6', '0', '0.1', '1', '2', '12', '11', '33', '24', '15', '14', '16', '10', '29', '18', '14', '7', '9', '', '1', '2', '13', '4', '22', '3', '2', '18', '5', '4', '12', '12', '7', '17', '5', '4', '', '1', '0', '0', '0'], 2.629990069462563, 0.015524329641908101, ['REJECT H0']), ('Q3', ['15', '4', 'Q3', '3', '1', '0', '0.05', '1', '1', '27', '8', '60', '', '1', '28', '8', '45', '', '0', '0', '0'], -0.6338656910463873, 0.2638464442293141, ['FAIL TO REJECT H0']), ('Q4', ['15', '4', 'Q4', '1', '1', '0', '0.01', '1', '2', '8', '8', '6', '5', '4', '6', '6', '5', '5', '', '1', '2', '10', '6', '8', '8', '7', '8', '6', '7', '7', '6', '6', '', '1', '0', '0', '0'], -2.5348065190327085, 0.012716830896249975, ['FAIL TO REJECT H0']), ('Q5', ['15', '4', 'Q5', '3', '2', '0', '0.1', '1', '1', '27', '15', '51', '', '1', '26', '12', '40', '', '0', '0', '0'], 0.35329371124087317, 0.3623520665070009, ['FAIL TO REJECT H0']), ('Q7', ['15', '4', 'Q7', '1', '2', '0', '0.03', '1', '2', '38', '1203344', '1441636', '1535140', '1688990', '1420416', '1635918', '1650348', '1360810', '1663407', '1512571', '1441045', '1431893', '1523045', '1366346', '1299471', '1431891', '1578698', '1663408', '1292641', '1319737', '1326402', '1535137', '1578699', '1650207', '1410213', '1574808', '1432033', '1480171', '1502702', '1535138', '1317156', '1299470', '1503005', '1463498', '1288971', '1583940', '1474790', '1431890', '', '2', '35', '1563593', '1317885', '1066075', '1354054', '1636119', '1487885', '1499983', '1483763', '1325525', '1368378', '1363859', '1588573', '1688950', '1690182', '1238979', '1177002', '1648209', '1476254', '1861990', '1499984', '1420249', '1861991', '1354649', '1331776', '1297326', '1286638', '1569413', '1337827', '1297328', '1387893', '1331777', '1066074', '1861992', '1297327', '1588132', '', '0', '0', '0'], 0.5835180673664734, 0.2809481950115834, ['FAIL TO REJECT H0']), ('Q7 CI', ['11', '5', '1469710.1315789474', '125069.77869674389', '38', '1446503.8285714285', '202359.40246320126', '35', '94%', '0', '0'], None, None, ['INTERVAL=(-53144.1294, 99556.7354)']), ('Q17', ['15', '3', 'before minus after pulse', '1', '1', '0', '.03', '2', '17', '-62', '-10', '-63', '-33', '-90', '-62', '-44', '-54', '-40', '-68', '-46', '-56', '-34', '-74', '-12', '-66', '-54', '', '1', '0', '0', '0'], -10.062711385943217, 1.2589229521779525e-08, ['REJECT H0']), ('Q17 CI', ['11', '3', '2', '17', '-62', '-10', '-63', '-33', '-90', '-62', '-44', '-54', '-40', '-68', '-46', '-56', '-34', '-74', '-12', '-66', '-54', '94%', '', '0', '0'], None, None, ['INTERVAL=(-61.3287, -40.7889)']), ('Q12 CI', ['11', '1', '80', '200', '95%', '0', '0'], None, None, ['p-hat=0.4000']), ('Q13 interval', ['11', '7', '1', '.30', '.024', '0', '0'], None, None, ['INTERVAL=(0.2760, 0.3240)'])]\nfor name,answers,statistic,probability,expected in cases:\n pending=iter(answers);pages=[];refs=[]\n def read(prompt=''):\n  try:return next(pending)\n  except StopIteration:raise AssertionError((name,prompt))\n def view(title,lines):\n  assert title!='CHECK ENTERED VALUES',(name,list(lines))\n  lines=list(lines);pages.extend(lines)\n  refs.extend(weakref.ref(sys.modules[n]) for n in c.topic_modules())\n  return viewer(title,lines)\n builtins.input=read;c.view=view\n with contextlib.redirect_stdout(io.StringIO()):STAT1.main()\n assert not list(pending),name\n assert not c.topic_modules() and all(ref() is None for ref in refs),name\n text='\\n'.join(pages)\n for value in expected:assert value in text,(name,value,text)\n if statistic is not None:\n  ts=float(next(line.rsplit('=',1)[1] for line in pages if line.startswith('TS=')))\n  p=float(next(line.split('=')[1] for line in pages if line.startswith('p-VALUE=')))\n  assert abs(ts-statistic)<1e-6,(name,ts,statistic)\n  assert abs(p-probability)<1e-7,(name,p,probability)\nprint('CH10B_WORKFLOWS_PASS')\n"
        result=subprocess.run([sys.executable,'-B','-c',code],cwd=Path(__file__).resolve().parent.parent,capture_output=True,text=True,timeout=60)
        self.assertEqual(result.returncode,0,result.stdout[-3000:]+result.stderr)
        self.assertIn('CH10B_WORKFLOWS_PASS',result.stdout)

if __name__=='__main__': unittest.main()
